// Fire-and-forget + event-driven progress (recommended via generateAwait)
const job = await anna.video.generateAwait({
  prompt: "Aerial drone shot over a misty pine forest at sunrise",
  durationSec: 5, resolution: "768p", aspectRatio: "16:9",
  clientTag: "scene-3-broll",
}, {
  onProgress: (p) => status.textContent = `${p.state} · queue ${p.progress?.queuePosition ?? '-'}`,
  timeoutMs: 10 * 60 * 1000,
});
videoEl.src = job.result.url;             // ~30 min TTL
videoEl.onerror = async () => { videoEl.src = await job.result.refreshUrl(); };
costEl.textContent = `${job.billedCostCU} CU`;

const view = await anna.video.getJob({ jobId });
if (view.state === 'succeeded') play(view.result.url);
else if (view.state === 'failed') showError(view.error?.message);

abortBtn.onclick = async () => {
  const r = await anna.video.cancelJob({ jobId });
  status.textContent = r.state === 'cancelled' ? 'Cancelled, CU refunded' : 'Too late — already rendering';
};

// Reload recovery
const { jobs } = await anna.video.listJobs({ state: 'running' });
for (const j of jobs) resumeTracking(j.jobId, j.clientTag);
